#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

int head[MAXN], to[MAXN * 2], nxt[MAXN * 2];
int edge_count = 0;

void add_edge(int u, int v) {
    to[edge_count] = v;
    nxt[edge_count] = head[u];
    head[u] = edge_count++;
}

int dp[MAXN][2]; // dp[u][0] = size of max matching in subtree when u is free
                 // dp[u][1] = size of max matching in subtree when u is matched with its parent

void dfs(int u, int parent) {
    dp[u][0] = 0;
    dp[u][1] = 0;
    int sum0 = 0;
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int v = to[e];
        if (v == parent) continue;
        dfs(v, u);
        sum0 += dp[v][0];
    }
    dp[u][1] = sum0; // u not matched with any child
    dp[u][0] = sum0; // initially same as not matched
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int v = to[e];
        if (v == parent) continue;
        int candidate = sum0 - dp[v][0] + dp[v][1] + 1;
        if (candidate > dp[u][0]) dp[u][0] = candidate;
    }
}

int main() {
    int N;
    scanf("%d", &N);
    for (int i = 1; i <= N; i++) head[i] = -1;
