}

#include <stdio.h>
#include <stdlib.h>

typedef struct Edge {
    int to, next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * 2 * (N - 1));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[ecnt] = (Edge){b, head[a]};
        head[a] = ecnt++;
        edges[ecnt] = (Edge){a, head[b]};
        head[b] = ecnt++;
        deg[a]++;
        deg[b]++;
    }

    /* Bipartite coloring of the tree */
    int *color = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) color[i] = -1;

    int *queue = (int *)malloc(sizeof(int) * N);
    int qh = 0, qt = 0;

    color[1] = 0;
    queue[qt++] = 1;

    int cnt[2] = {1, 0};

    while (qh < qt) {
        int v = queue[qh++];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (color[u] == -1) {
                color[u] = color[v] ^ 1;
                cnt[color[u]]++;
                queue[qt++] = u;
            }
        }
    }

    /*
      On a tree, Takahashi can ensure all his chosen vertices lie in one bipartition class.
      Since vertices within the same class are never adjacent, they survive the repainting step.
      So if one side has at least ceil(N/2) vertices, Takahashi can take that side on all his turns.
      Aoki wins only when both sides are < ceil(N/2), which is impossible.
      More concretely:
      - Takahashi moves ceil(N/2) times.
      - If max(cnt[0], cnt[1]) >= ceil(N/2), Takahashi wins.
      This always holds for a tree, but we keep the direct check.
    */
    int need = (N + 1) / 2;
    if (cnt[0] >= need || cnt[1] >= need) {
        printf("First\n");
    } else {
        printf("Second\n");
    }

    free(edges);
    free(head);
    free(deg);
    free(color);
    free(queue);
    return 0;
}

