public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        List<Integer>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }

        // This game is equivalent to whether Takahashi can secure
        // an independent set larger than Aoki's choices.
        // On a tree, bipartition vertices by parity of depth.
        // Since every edge connects opposite colors of the bipartition,
        // one side itself is an independent set.
        // Takahashi can always choose all vertices from the larger side,
        // so if that side has more than N/2 vertices, he wins.
        // Otherwise Aoki can make all white vertices adjacent to black.
        int[] color = new int[N];
        Arrays.fill(color, -1);

        int[] queue = new int[N];
        int head = 0, tail = 0;
        queue[tail++] = 0;
        color[0] = 0;
        int cnt0 = 1, cnt1 = 0;

        while (head < tail) {
            int v = queue[head++];
            for (int to : g[v]) {
                if (color[to] == -1) {
                    color[to] = color[v] ^ 1;
                    if (color[to] == 0) cnt0++;
                    else cnt1++;
                    queue[tail++] = to;
                }
            }
        }

        if (Math.max(cnt0, cnt1) > N / 2) {
            System.out.println("First");
        } else {
            System.out.println("Second");
        }
    }
}

